// ⚠ Fichier engendré par polices/engendrer.mjs — ne pas modifier à la main.
//
// Les polices du dossier PDF, en base64. Chromium imprime sans accès réseau : une police
// appelée depuis le réseau ne serait jamais chargée, et le document retomberait sur ce que
// le serveur a en magasin. Voir polices/LICENCES.md pour les familles et leurs droits.
//
// Poids total des fichiers : 122 Ko, soit 162 Ko une fois encodés.
// Chromium n'incorpore au PDF que les glyphes réellement employés : le document produit
// reste léger.

const POLICES = {
  /** Hanken Grotesk 100 900 — HankenGrotesk-variable-latin.woff2, 34704 octets. */
  texte: '',
  /** Spectral 400 — Spectral-400-latin.woff2, 21696 octets. */
  titreNormal: '',
  /** Spectral 600 — Spectral-600-latin.woff2, 22936 octets. */
  titreGras: '',
  /** IBM Plex Mono 400 — IBMPlexMono-400-latin.woff2, 14708 octets. */
  chiffresNormal: '',
  /** IBM Plex Mono 500 — IBMPlexMono-500-latin.woff2, 14888 octets. */
  chiffresMoyen: '',
  /** IBM Plex Mono 600 — IBMPlexMono-600-latin.woff2, 15620 octets. */
  chiffresGras: '',
} as const;

/** Règles @font-face à placer en tête de la feuille de style du document. */
export const REGLES_POLICES = `
  @font-face {
    font-family: 'Hanken Grotesk';
    font-weight: 100 900;
    font-style: normal;
    font-display: block;
    src: url(data:font/woff2;base64,${POLICES.texte}) format('woff2');
  }
  @font-face {
    font-family: 'Spectral';
    font-weight: 400;
    font-style: normal;
    font-display: block;
    src: url(data:font/woff2;base64,${POLICES.titreNormal}) format('woff2');
  }
  @font-face {
    font-family: 'Spectral';
    font-weight: 600;
    font-style: normal;
    font-display: block;
    src: url(data:font/woff2;base64,${POLICES.titreGras}) format('woff2');
  }
  @font-face {
    font-family: 'IBM Plex Mono';
    font-weight: 400;
    font-style: normal;
    font-display: block;
    src: url(data:font/woff2;base64,${POLICES.chiffresNormal}) format('woff2');
  }
  @font-face {
    font-family: 'IBM Plex Mono';
    font-weight: 500;
    font-style: normal;
    font-display: block;
    src: url(data:font/woff2;base64,${POLICES.chiffresMoyen}) format('woff2');
  }
  @font-face {
    font-family: 'IBM Plex Mono';
    font-weight: 600;
    font-style: normal;
    font-display: block;
    src: url(data:font/woff2;base64,${POLICES.chiffresGras}) format('woff2');
  }
`;

/**
 * Les deux seules faces reprises dans le gabarit de pied de page, 48 Ko.
 *
 * Le gabarit natif de Chromium est rendu dans un document isolé qui n'hérite pas de la
 * feuille de style du dossier : sans ces règles, le pied serait la seule ligne du document
 * composée dans la police du système.
 */
export const REGLES_POLICES_PIED = `
@font-face {
  font-family: 'Hanken Grotesk';
  font-weight: 100 900;
  font-style: normal;
  font-display: block;
  src: url(data:font/woff2;base64,${POLICES.texte}) format('woff2');
}
@font-face {
  font-family: 'IBM Plex Mono';
  font-weight: 500;
  font-style: normal;
  font-display: block;
  src: url(data:font/woff2;base64,${POLICES.chiffresMoyen}) format('woff2');
}
`;
